function toQty(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

// pgStockRows: [{ sku, qty }, ...] -- one row per 300/310/400 code that
// matched some incoming SKU's 8-digit body, from the 'Look up stock'
// Postgres node (one parameterised query per incoming row, substr(sku, 4)
// = the body). Builds a lookup keyed on the ORIGINAL 300 sku (since every
// row in the attachment is a finished-good 300 code, and '300' + body is
// always that same sku), mapping to a { '300': qty, '310': qty, '400': qty }
// record so a row can see all three stock levels for its product.
function buildStockIndex(pgStockRows) {
  const index = new Map();
  for (const r of pgStockRows || []) {
    const sku = String(r.sku).trim();
    if (sku.length < 4) continue;
    const prefix = sku.slice(0, 3);
    const body = sku.slice(3);
    const key = `300${body}`;
    if (!index.has(key)) {
      index.set(key, {});
    }
    index.get(key)[prefix] = toQty(r.qty);
  }
  return index;
}

// row: { sku, qty, ... } -- qty is the quantity asked for in the email
// stockIndex: Map from buildStockIndex()
// rules: [{ prefix, stage, nextStep, checkOrder }, ...] read from the
//        'routing' table -- nothing about prefix-to-step mapping or check
//        order is hardcoded here, only the shape of a rule row.
function decideNextStep(row, stockIndex, rules) {
  if (!Array.isArray(rules) || rules.length === 0) {
    throw new Error('Routing rules are missing or empty -- refusing to guess a next step.');
  }

  const sorted = [...rules].sort((a, b) => Number(a.checkOrder) - Number(b.checkOrder));

  for (const rule of sorted) {
    if (!rule || typeof rule.prefix !== 'string' || typeof rule.nextStep !== 'string') {
      throw new Error('A routing rule is missing "prefix" or "nextStep" -- refusing to guess a next step.');
    }
  }

  const fallback = sorted.find((r) => r.prefix === 'none');
  if (!fallback) {
    throw new Error('Routing rules have no "none" fallback row -- refusing to guess a next step.');
  }

  const record = stockIndex.get(String(row.sku).trim());
  if (!record) {
    return 'SKU NOT FOUND';
  }

  // The row's own level (its sku prefix: the finished 300 code) only
  // counts when that stock covers the qty asked for; any other level
  // counts as soon as it has stock > 0.
  const ownPrefix = String(row.sku).trim().slice(0, 3);
  const demand = toQty(row.qty);
  for (const rule of sorted) {
    if (rule.prefix === 'none') continue;
    const qty = record[rule.prefix];
    if (typeof qty !== 'number' || qty <= 0) continue;
    if (rule.prefix === ownPrefix && qty < demand) continue;
    return rule.nextStep;
  }

  return fallback.nextStep;
}

// qty: the row's own qty cell; nextStep: decideNextStep()'s result.
// Builds the 'actions' cell, e.g. "20 to Edge and drill". A blank qty
// leaves just the step rather than writing "undefined to ...".
function formatAction(qty, nextStep) {
  const q = qty === null || qty === undefined ? '' : String(qty).trim();
  return q === '' ? nextStep : `${q} to ${nextStep}`;
}

// incomingRows: the attachment's rows. Returns the rows to send back,
// each with its 'actions' cell. A row whose own finished stock covers its
// qty (decideNextStep() chose the rule for the row's own prefix) needs
// nothing doing, so it is left out of the reply.
function buildResultRows(incomingRows, stockIndex, rules) {
  const out = [];
  for (const row of incomingRows || []) {
    const step = decideNextStep(row, stockIndex, rules);
    const ownRule = rules.find((r) => r.prefix === String(row.sku).trim().slice(0, 3));
    if (ownRule && step === ownRule.nextStep) continue;
    // 'SKU NOT FOUND' is not a step to do, so no qty goes in front of it.
    const actions = step === 'SKU NOT FOUND' ? step : formatAction(row.qty, step);
    out.push({ ...row, actions });
  }
  return out;
}

/* ---- n8n glue below: not unit-tested here, see README ---- */

// Pull each upstream node's full output directly by name, regardless of
// what flows through this node's own main input -- this keeps the three
// pure-function inputs (rows / stock rows / rules rows) decoupled from
// the linear chain they happen to be wired through in the canvas.
const incomingRows = $('Read xlsx attachment').all().map((item) => item.json);

const stockRows = $('Look up stock').all().map((item) => ({
  sku: item.json.sku,
  qty: item.json.qty,
}));

const rulesRows = $('Read routing rules').all().map((item) => {
  const j = item.json;
  return {
    prefix: String(j.prefix).trim(),
    stage: j.stage,
    nextStep: j.next_step,
    checkOrder: j.check_order,
  };
});

const stockIndex = buildStockIndex(stockRows);

return buildResultRows(incomingRows, stockIndex, rulesRows).map((json) => ({ json }));
